package com.stocksense.product; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api") @RequiredArgsConstructor public class ProductController { private final ProductRepository products; private final CategoryRepository categories; @GetMapping("/products") public List<Product> products(){return products.findAll();} @PostMapping("/products") public ResponseEntity<?> product(@RequestBody Product p){if(p.getSku()==null||p.getSku().isBlank()||p.getName()==null||p.getName().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Name and SKU are required")); if(products.existsBySkuIgnoreCase(p.getSku()))return ResponseEntity.status(409).body(Map.of("message","SKU already exists")); if(p.getMinimumStock().signum()<0||p.getReorderQuantity().signum()<0)return ResponseEntity.badRequest().body(Map.of("message","Stock rules cannot be negative"));return ResponseEntity.ok(products.save(p));} @PutMapping("/products/{id}") public Product update(@PathVariable Long id,@RequestBody Product p){Product e=products.findById(id).orElseThrow(); e.setName(p.getName());e.setUnitOfMeasure(p.getUnitOfMeasure());e.setMinimumStock(p.getMinimumStock());e.setReorderQuantity(p.getReorderQuantity());e.setBarcode(p.getBarcode());e.setActive(p.isActive());return products.save(e);} @GetMapping("/categories") public List<Category> categories(){return categories.findAll();} @PostMapping("/categories") public Category category(@RequestBody Category c){return categories.save(c);} }
